import { describe, it, expect } from 'vitest';
import git from 'isomorphic-git';
import {
  createTestContext,
  recordEvent,
  replayEvents,
  getDatabase,
  insertNode,
  type HiveContext,
  type Node,
} from '@hive/core';

const branch = 'hive-test';

async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}

async function addNode(ctx: HiveContext, title: string): Promise<string> {
  const id = await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: title, confidence: 90 }, branch);
  const db = getDatabase(ctx);
  const now = new Date().toISOString();
  const node: Node = { change_id: id, branch, node_type: 'decision', title, status: 'pending', created_at: now, updated_at: now };
  insertNode(db, node);
  return id;
}

describe('parseGitLog resilience during a full rebuild', () => {
  it('keeps every valid node materialized when one id-less commit sits in the branch history', async () => {
    const { ctx } = await bootstrap();

    // Two well-formed add events -> two valid decision nodes with parseable commits.
    await addNode(ctx, 'Alpha');
    await addNode(ctx, 'Beta');

    // A hand-written commit whose subject matches /^\w+:\s*.+$/ but whose body carries no `id:` line.
    await ctx.git.commitToBranch('chore: bump deps', branch, { allowEmpty: true });

    // Force a full rebuild: DELETE FROM nodes/edges/... (lines 294-297) then replay every commit
    // returned by parseGitLog (line 300) into the freshly-cleared branch view.
    await replayEvents(ctx, branch, true);

    const db = getDatabase(ctx);
    const row = db.prepare('SELECT COUNT(*) AS c FROM nodes WHERE branch = ?').get(branch) as { c: number };

    // One malformed commit anywhere in the history must not erase the whole branch's view.
    expect(row.c).toBe(2);
  });
});
